content='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    # Locate rectangular outlined frames by their constant-color horizontal and vertical edges.
    frames = []
    colors = {v for row in grid for v in row if v not in (0,)}
    for color in colors:
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 3]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 3]
        # Find bounding boxes for connected components of each color; accept hollow rectangles.
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen:
                    continue
                stack=[(r,c)]; seen.add((r,c)); pts=[]
                while stack:
                    y,x=stack.pop(); pts.append((y,x))
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if r1-r0>=2 and c1-c0>=2 and all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1)):
                    frames.append((r0,c0,r1,c1,color))
    # The marker color is identified by its frequency matching the checkerboard count inside a frame.
    marker_colors = [v for v in colors if v not in {f[4] for f in frames}]
    for r0,c0,r1,c1,border in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1): out[r][c]=border
        n=sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1) if (r-r0-1+c-c0-1)%2==0)
        fill=min(marker_colors, key=lambda v: abs(sum(x==v for row in grid for x in row)-n)) if marker_colors else 0
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r-r0-1+c-c0-1)%2==0: out[r][c]=fill
    return out
'''
